create extension if not exists pg_cron;
create schema if not exists private;
revoke all on schema private from public;
create or replace function private.cleanup_expired_financial_history() returns void language plpgsql security definer set search_path='' as $$declare profile_row record;cutoff_date date;begin for profile_row in select id,greatest(retention_months,1) as retention_months from public.profiles loop cutoff_date:=(date_trunc('month',current_date)-make_interval(months=>profile_row.retention_months-1))::date;delete from public.transactions where user_id=profile_row.id and occurred_on<cutoff_date;delete from public.work_sessions where user_id=profile_row.id and worked_on<cutoff_date;delete from public.recurring_bill_payments where user_id=profile_row.id and due_month<cutoff_date;delete from public.card_bill_payments where user_id=profile_row.id and statement_month<cutoff_date;delete from public.card_installments where user_id=profile_row.id and billing_month<cutoff_date and paid_at is not null;delete from public.card_purchases p where p.user_id=profile_row.id and p.purchased_on<cutoff_date and not exists(select 1 from public.card_installments i where i.purchase_id=p.id);end loop;end;$$;
revoke all on function private.cleanup_expired_financial_history() from public,anon,authenticated;
do $$declare existing_job bigint;begin select jobid into existing_job from cron.job where jobname='devinx_retention_monthly' limit 1;if existing_job is not null then perform cron.unschedule(existing_job);end if;perform cron.schedule('devinx_retention_monthly','20 3 1 * *','select private.cleanup_expired_financial_history();');end $$;
